/** Deduped by kanji word. */
export const KANJI_BY_KEY: Record<string, KanjiWord> = {};

for (const [level, kanji, reading, meaning] of KANJI_WORDS) {
  const key = `${level}:${kanji}`;
  if (!(key in KANJI_BY_KEY)) {
    KANJI_BY_KEY[key] = { kanji, reading, meaning, level };
  }
}

const LEVEL_CACHE: Record<number, KanjiWord[]> = {};

/** All kanji words for a given JLPT level. */
export function kanjiWordsForLevel(level: number): KanjiWord[] {
  if (LEVEL_CACHE[level]) return LEVEL_CACHE[level];
  const list = Object.values(KANJI_BY_KEY).filter((w) => w.level === level);
  LEVEL_CACHE[level] = list;
  return list;
}

/** History of drawn kanji per pool key, so consecutive picks avoid repeats. */
const DRAW_HISTORY: Record<string, string[]> = {};

function drawFromPool(poolKey: string, pool: KanjiWord[]): KanjiWord | null {
  if (pool.length === 0) return null;
  const used = new Set(DRAW_HISTORY[poolKey] || []);
  const available = pool
    .map((w, i) => ({ w, i }))
    .filter(({ w }) => !used.has(w.kanji));
  let chosen: KanjiWord;
  if (available.length === 0) {
    DRAW_HISTORY[poolKey] = [];
    chosen = pool[Math.floor(Math.random() * pool.length)];
  } else {
    chosen = available[Math.floor(Math.random() * available.length)].w;
  }
  const history = [...(DRAW_HISTORY[poolKey] || [])];
  history.push(chosen.kanji);
  DRAW_HISTORY[poolKey] = history.slice(-pool.length);
  return chosen;
}

/** Draw a kanji word for a level, avoiding same-pool repeats. */
export function drawKanji(level: number): KanjiWord | null {
  return drawFromPool(`level:${level}`, kanjiWordsForLevel(level));
}
